CREATE TABLE reading_session (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,work_id UUID NOT NULL,edition_id UUID NOT NULL,started_chapter_id UUID,current_chapter_id UUID,started_locator_kind VARCHAR(32),started_locator_value VARCHAR(2048),current_locator_kind VARCHAR(32),current_locator_value VARCHAR(2048),started_at TIMESTAMPTZ NOT NULL,last_active_at TIMESTAMPTZ NOT NULL,ended_at TIMESTAMPTZ,offline BOOLEAN NOT NULL DEFAULT FALSE,version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(work_id) REFERENCES reading_work(id),FOREIGN KEY(edition_id) REFERENCES reading_edition(id),FOREIGN KEY(started_chapter_id) REFERENCES reading_chapter(id),FOREIGN KEY(current_chapter_id) REFERENCES reading_chapter(id));
CREATE TABLE reading_progress (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,work_id UUID NOT NULL,edition_id UUID NOT NULL,chapter_id UUID,locator_kind VARCHAR(32) NOT NULL,locator_value VARCHAR(2048) NOT NULL,content_version VARCHAR(128),completed BOOLEAN NOT NULL DEFAULT FALSE,intent VARCHAR(32) NOT NULL,source_session_id UUID,updated_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(work_id) REFERENCES reading_work(id),FOREIGN KEY(edition_id) REFERENCES reading_edition(id),FOREIGN KEY(chapter_id) REFERENCES reading_chapter(id),FOREIGN KEY(source_session_id) REFERENCES reading_session(id),UNIQUE(owner_id,work_id,edition_id));
CREATE TABLE reading_history (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,work_id UUID NOT NULL,chapter_id UUID,started_at TIMESTAMPTZ NOT NULL,ended_at TIMESTAMPTZ NOT NULL,duration_seconds BIGINT NOT NULL DEFAULT 0,start_locator VARCHAR(4096),end_locator VARCHAR(4096),CHECK(duration_seconds>=0),FOREIGN KEY(work_id) REFERENCES reading_work(id),FOREIGN KEY(chapter_id) REFERENCES reading_chapter(id));
CREATE INDEX idx_reading_history_owner ON reading_history(owner_id,ended_at DESC);
